    "rutOrganismo": "61.608.104-7",
    "tipoOficial": "LP",
    "tipoNombre": "Licitación Pública >100 UTM",
    "titulo": "PCR CUANTITATIVA DE POLIOMAVIRUS BK Y EPSTEIN BARR",
    "organismo": "SERVICIO DE SALUD SUR HOSPITAL LUCIO CORDOVA",
    "organismoRut": "61.608.104-7",
    "organismoPagoDias": null,
    "organismoRiesgo": "Sin evaluar",
    "rubro": "Artículos de Escritorio y Oficina",
