    "rutOrganismo": "61.608.101-2",
    "tipoOficial": "LE",
    "tipoNombre": "Licitación Pública >1000 UTM",
    "titulo": "CGM ADQUISICIÓN DE MONITOR MULTIPARAMETROS",
    "organismo": "SERVICIO DE SALUD METROPOLITANO SUR HOSP",
    "organismoRut": "61.608.101-2",
