    "id_orden_compra": null,
    "codigoOrdenCompra": null,
    "rutOrganismo": "61.608.406-2",
    "tipoOficial": "LP",
    "tipoNombre": "Licitación Pública >100 UTM",
    "titulo": "Arriendo de Huelleros digitales y Pistola Escáner",
    "organismo": "SERVICIO DE SALUD ORIENTE HOSPITAL DEL SALVADOR",
    "organismoRut": "61.608.406-2",
    "organismoPagoDias": null,
    "organismoRiesgo": "Sin evaluar",
    "rubro": "Artículos de Escritorio y Oficina",
    "region": "Región Metropolitana de Santiago",
    "monto": 160000000,
    "amount": 160000000,
    "amountType": "monto_estimado",
    "currency": "CLP",
    "fechaPublicacion": "2026-09-10T16:49:37.437",
